using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00006 : ControllerTestBase
    {
        [TestMethod]
        public void ApiExplorerSettings_GroupName_Attribute_Have_To_Be_Set()
        {
            var missingApiControllerAttributes = (from controller in Controllers
                                                  from attribute in controller.Attributes
                                                  where attribute.Name.Contains("ApiExplorerSettings") &&
                                                        !attribute.Arguments.Any(attribute => attribute.Contains("GroupName"))
                                                  select new
                                                  {
                                                      ErrorClass = controller.FullQualifiedName,
                                                      Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Class:      {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: 

{controller.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

[ApiExplorerSettings(GroupName = ""User"")]
{controller.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                                  }).ToImmutableList();

            Assert.IsTrue(missingApiControllerAttributes.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00006

Missing [ApiExplorerSettings] GroupName declaration for controller detected. Findings {missingApiControllerAttributes.Count}': {Environment.NewLine}{missingApiControllerAttributes.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }


